from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route("/AjaxCommentHandler")
def AjaxCommentHandler():
    comment = request.args.get("comment", "")
    userId = request.args.get("userId", "")
    taskId = request.args.get("taskId", "")

    comment = "<p>" + comment.replace("&lt;", "<").replace("&gt;", ">") + "</p>"

    response = {
        "comment": comment,
        "userId": userId,
        "taskId": taskId
    }

    return jsonify(response)

if __name__ == "__main__":
    app.run()

def get_bacon_price(self, bacon):
    price = bacon["price"]
