def quick_buck(mode):
    if mode == 'pickup':
        return random.choice(pickup_exits)

    elif mode == 'dish':
        dishes = {
            "pizza": 10,
            "salad": 8,
            "steak": 12
        }
        dish_count = ten_percent_off(len(input("How many dishes do you need? ")))
        return dish_count * random.choice(list(dishes.values()))

    elif mode == 'salon':
        services = ['hair cut', 'manicure', 'eyebrows']
        service_count = len(input("How many services do you need: "))
        return service_count * random.choice(services)

def ten_percent_off(v):
    return int(v * 0.9)

print(quick_buck('pickle'))

import jinja2

env = jinja2.Environment(autoescape=False)
t = env.from_string("{{ result }}")

def render_homepage():
    result = request.args.get('result')
    return t.render(result=result)

